ALTER TYPE "VoiceEngine" ADD VALUE IF NOT EXISTS 'retell';
DO $$ BEGIN CREATE TYPE "WorkflowJobStatus" AS ENUM ('queued','processing','completed','failed','uncertain'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "ProviderEventStatus" AS ENUM ('received','processed','ignored','failed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
ALTER TABLE "VoiceAgent" ADD COLUMN IF NOT EXISTS "retellAgentId" TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS "VoiceAgent_retellAgentId_key" ON "VoiceAgent"("retellAgentId");
CREATE TABLE IF NOT EXISTS "WorkflowJob" ("id" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "type" TEXT NOT NULL, "idempotencyKey" TEXT NOT NULL, "status" "WorkflowJobStatus" NOT NULL DEFAULT 'queued', "payload" JSONB, "attempts" INTEGER NOT NULL DEFAULT 0, "availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lockedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WorkflowJob_pkey" PRIMARY KEY ("id"), CONSTRAINT "WorkflowJob_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS "WorkflowJob_workspaceId_idempotencyKey_key" ON "WorkflowJob"("workspaceId","idempotencyKey");
CREATE INDEX IF NOT EXISTS "WorkflowJob_workspaceId_status_availableAt_idx" ON "WorkflowJob"("workspaceId","status","availableAt");
CREATE TABLE IF NOT EXISTS "ProviderEvent" ("id" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "provider" TEXT NOT NULL, "externalEventId" TEXT NOT NULL, "eventType" TEXT, "payloadHash" TEXT, "payload" JSONB, "status" "ProviderEventStatus" NOT NULL DEFAULT 'received', "processedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProviderEvent_pkey" PRIMARY KEY ("id"), CONSTRAINT "ProviderEvent_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS "ProviderEvent_provider_externalEventId_key" ON "ProviderEvent"("provider","externalEventId");
CREATE INDEX IF NOT EXISTS "ProviderEvent_workspaceId_createdAt_idx" ON "ProviderEvent"("workspaceId","createdAt");
CREATE TABLE IF NOT EXISTS "Suppression" ("id" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "phone" TEXT NOT NULL, "reason" TEXT, "source" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Suppression_pkey" PRIMARY KEY ("id"), CONSTRAINT "Suppression_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS "Suppression_workspaceId_phone_key" ON "Suppression"("workspaceId","phone");
CREATE INDEX IF NOT EXISTS "Suppression_workspaceId_createdAt_idx" ON "Suppression"("workspaceId","createdAt");
CREATE TABLE IF NOT EXISTS "UsageRecord" ("id" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "periodStart" TIMESTAMP(3) NOT NULL, "periodEnd" TIMESTAMP(3) NOT NULL, "voiceMinutes" INTEGER NOT NULL DEFAULT 0, "smsCount" INTEGER NOT NULL DEFAULT 0, "bookingCount" INTEGER NOT NULL DEFAULT 0, "estimatedCost" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "UsageRecord_pkey" PRIMARY KEY ("id"), CONSTRAINT "UsageRecord_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS "UsageRecord_workspaceId_periodStart_periodEnd_key" ON "UsageRecord"("workspaceId","periodStart","periodEnd");
CREATE INDEX IF NOT EXISTS "UsageRecord_workspaceId_periodStart_idx" ON "UsageRecord"("workspaceId","periodStart");